<?php use App\Helpers\FormatHelper; ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="fw-bold mb-0">Timesheet</h4><p class="text-muted small mb-0">Controle de horas por processo/cliente.</p></div></div>
<div class="row g-3 mb-3"><div class="col-md-6"><div class="card"><div class="card-body"><div class="text-muted small">Horas lançadas</div><div class="fs-4 fw-bold"><?= number_format((float)(($summary['minutos'] ?? 0)/60),2,',','.') ?>h</div></div></div></div><div class="col-md-6"><div class="card"><div class="card-body"><div class="text-muted small">Valor potencial</div><div class="fs-4 fw-bold"><?= FormatHelper::money((float)($summary['valor'] ?? 0)) ?></div></div></div></div></div>
<div class="card mb-3"><div class="card-header">Novo lançamento</div><div class="card-body"><form id="timesheetForm" class="row g-2"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($csrf_token ?? '', ENT_QUOTES, 'UTF-8') ?>"><div class="col-md-2"><label class="form-label">Data</label><input type="date" name="data" class="form-control" value="<?= date('Y-m-d') ?>"></div><div class="col-md-2"><label class="form-label">Início</label><input type="time" name="inicio" class="form-control"></div><div class="col-md-2"><label class="form-label">Fim</label><input type="time" name="fim" class="form-control"></div><div class="col-md-2"><label class="form-label">Minutos</label><input type="number" name="minutos" class="form-control" value="60"></div><div class="col-md-2"><label class="form-label">Valor/hora</label><input type="text" name="valor_hora" class="form-control" value="0,00"></div><div class="col-md-6"><label class="form-label">Processo</label><select name="case_id" class="form-select"><option value="">Sem processo</option><?php foreach($cases as $c): ?><option value="<?= $c['id'] ?>"><?= htmlspecialchars($c['numero_cnj'] ?: $c['assunto'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Cliente</label><select name="client_id" class="form-select"><option value="">Sem cliente</option><?php foreach($clients as $cl): ?><option value="<?= $cl['id'] ?>"><?= htmlspecialchars($cl['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-12"><label class="form-label">Descrição</label><textarea name="descricao" class="form-control" required></textarea></div><div class="col-md-12"><label><input type="checkbox" name="faturavel" checked> Faturável</label></div><div class="col-md-12"><button class="btn btn-primary">Salvar</button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Data</th><th>Processo</th><th>Cliente</th><th>Horas</th><th>Descrição</th></tr></thead><tbody><?php foreach($entries as $e): ?><tr><td><?= date('d/m/Y', strtotime($e['data'])) ?></td><td><?= htmlspecialchars($e['numero_cnj'] ?? '-', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($e['client_name'] ?? '-', ENT_QUOTES, 'UTF-8') ?></td><td><?= number_format(((int)$e['minutos'])/60,2,',','.') ?>h</td><td><?= htmlspecialchars($e['descricao'], ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<script>document.getElementById('timesheetForm')?.addEventListener('submit',function(e){e.preventDefault();fetch((window.APP_BASE_PATH || '') + '/timesheets/store',{method:'POST',body:new FormData(this)}).then(r=>r.json()).then(d=>{alert(d.message); if(d.success) location.reload();});});</script>
